import time

from robot.api import logger as robot_logger

from ...exceptions import IperfStartFailed
from ..data_transfer_utilities import get_at_uepc_ip
from ..iperf.at_iperf_data_transfer import AtIperfDataTransfer


class AtIperfUePcDataTransfer(AtIperfDataTransfer):
    """AtIperfDataTransfer class"""

    def __init__(self, name, ue_pc, com_port, dt_definition, configuration):
        """
        :param name: alias of data transfer
        :param ue_pc: Rpc object responsible for HTTP/HTTPS request
        :param com_port: UE com port
        :param dt_definition: object containing data transfer's details
        :param configuration: UE configuration from config yaml file
        """
        super().__init__(name, ue_pc, com_port, dt_definition, configuration)

    def start(self):
        """
        Starts data transfer with parameters defined in dt_definition passed during initialization.
        :return: None
        """
        self._check_prompt(prompt=self._get_app_server_prompt(), scope="AppServer")
        try:
            command_moler = "iperf2" if self.dt_config['version'] == 2 else "iperf3"
            command_name = command_moler.replace('iperf2', 'iperf')
            ue_pc_ip = self.dt_config['ue_pc_host']
            ue_iperf_cmd = self._build_ue_iperf_command()
            iperf_cmd_log_ue = f"IPERF CMD (UE=({self.com_port} {self.ue_ip}) from UE_PC={ue_pc_ip}): {command_name} {ue_iperf_cmd}"
            self.logger.info(iperf_cmd_log_ue)
            robot_logger.info(iperf_cmd_log_ue)
            appserver_iperf_cmd = self._build_app_server_iperf_command()
            iperf_cmd_log_app_server = f"IPERF CMD (APP SERVER={self.app_server_ip}): {command_name} {appserver_iperf_cmd}"
            self.logger.info(iperf_cmd_log_app_server)
            robot_logger.info(iperf_cmd_log_app_server)
            self.iperf_cmd = self.moler_device.get_cmd(cmd_name=command_moler, cmd_params={'options': appserver_iperf_cmd})
            self.iperf_cmd.set_timeout_action(action='z')  # new in moler 3.3.0

            access_prefix = (self._configuration.get("sub_access", "At") or "At").capitalize()
            dt_class = f"{access_prefix}UePcIperf" if self.dt_config['version'] == 2 else f"{access_prefix}UePcIperf3"
            if self.dt_config["direction"] == "ul":
                iperf_cmd_timeout = self.dt_config["duration"] + 5
                self.logger.debug(f"iperf cmd timeout: {iperf_cmd_timeout}")
                self.iperf_cmd.start(timeout=iperf_cmd_timeout)
                time.sleep(2)
                self.logger.debug(f"SERVER STARTED: {self.iperf_cmd}")
                if self.iperf_cmd.done():
                    raise IperfStartFailed(f"start cmd \"{command_name} {appserver_iperf_cmd}\" failed")
                ue_pc_dt_info = \
                    self.ue_pc.start_data_transfer(ue_id=self.com_port,
                                                   data_transfer_config={
                                                       'data_transfer_cmd': ue_iperf_cmd,
                                                       'iperf_path': self.dt_config['iperf_path'],
                                                       'timeout': iperf_cmd_timeout,
                                                       'ue_pc': {
                                                           'host': self.dt_config['ue_pc_host'],
                                                           'login': self.dt_config['ue_pc_login'],
                                                           'password': self.dt_config['ue_pc_password']},
                                                       'ue_pc_expected_prompt': self.dt_config['ue_pc_expected_prompt'],
                                                       'app_server_host' : self.dt_config['app_server_host'],
                                                   },
                                                   data_transfer_id=self.dt_id,
                                                   data_transfer_class=dt_class)
                self._check_ue_pc_dt_info(ue_pc_dt_info)
                self.logger.debug(f"CLIENT STARTED: {ue_iperf_cmd}")
            elif self.dt_config["direction"] == "dl":
                iperf_cmd_timeout = self.dt_config["duration"] + 3
                self.logger.debug(f"iperf cmd timeout: {iperf_cmd_timeout}")
                ue_pc_dt_info = \
                    self.ue_pc.start_data_transfer(ue_id=self.com_port,
                                                   data_transfer_config={
                                                       'data_transfer_cmd': ue_iperf_cmd,
                                                       'iperf_path': self.dt_config['iperf_path'],
                                                       'timeout': iperf_cmd_timeout,
                                                       'ue_pc': {
                                                           'host': self.dt_config['ue_pc_host'],
                                                           'login': self.dt_config['ue_pc_login'],
                                                           'password': self.dt_config['ue_pc_password']},
                                                       'ue_pc_expected_prompt': self.dt_config['ue_pc_expected_prompt']
                                                   },
                                                   data_transfer_id=self.dt_id,
                                                   data_transfer_class=dt_class)
                time.sleep(2)
                self._check_ue_pc_dt_info(ue_pc_dt_info)
                if not self._verify_start_iperf_on_ue():
                    raise IperfStartFailed(f"start cmd \"{command_name} {ue_iperf_cmd}\" failed")
                self.logger.debug(f"SERVER STARTED: {ue_iperf_cmd}")
                self.iperf_cmd.start(timeout=iperf_cmd_timeout)
                self.logger.debug(f"CLIENT STARTED: {self.iperf_cmd}")
            self._wait_for_iperf_client_startup(cmd_name=command_name, cmd_ue_pc=ue_iperf_cmd,
                                                cmd_app_server=appserver_iperf_cmd)
        except Exception as exc:
            self.logger.debug("Exception during starting DT, stopping iPerf processes")
            self._safely_try_to_stop_iperfs()
            raise exc

    def _check_ue_pc_dt_info(self, ue_pc_dt_info):
        if ue_pc_dt_info:
            robot_logger.debug(f"UE_PC details: {ue_pc_dt_info}")
            self._check_prompt(prompt=ue_pc_dt_info.get("prompt"))

    @property
    def ue_ip(self):
        if not self._ue_ip:
            self._ue_ip = get_at_uepc_ip(ue_pc=self.ue_pc,
                                         ue_id=self.com_port,
                                         logger=self.logger,
                                         interface=self.dt_config['interface_at_ue_pc'],
                                         apn=self.dt_config['apn'],
                                         timeout=10)
        return self._ue_ip

    def _build_dt_config(self, dt_definition, configuration):
        dt_config = {
            'app_server_host': configuration['data_transfer']['iperf']['app_server']['address'],
            'app_server_login': configuration['data_transfer']['iperf']['app_server']['user'],
            'app_server_password': configuration['data_transfer']['iperf']['app_server']['password'],
            'app_server_prompt': configuration['data_transfer']['iperf']['app_server']['expected_prompt'],
            'app_server_bind_interface_ip':
                configuration['data_transfer']['iperf']['app_server'].get('bind_interface_ip', None),
            'ue_pc_host': configuration['ue_pc_address'],
            'ue_pc_login': configuration['ue_pc_login'],
            'ue_pc_password': configuration['ue_pc_password'],
            'iperf_path': configuration['data_transfer']['iperf'].get('binary_path', None),
            'ue_pc_expected_prompt': configuration['ue_pc_expected_prompt'],
            'interface_at_ue_pc': configuration['data_transfer']['iperf'].get('interface_name', None),
            'protocol': dt_definition.protocol,
            'duration': dt_definition.duration if dt_definition.duration != 863913600.0 else 86400.0,
            'throughput': dt_definition.throughput,
            'direction': dt_definition.direction,
            'port': dt_definition.protocol_details.get('port', None),
            'version': self._get_dt_iperf_version(dt_definition.protocol_details,
                                                  configuration['data_transfer']['iperf']),
            'buffer': dt_definition.protocol_details.get('buffer', None),
            'parallel_streams': dt_definition.protocol_details.get('parallel_streams', None),
            'max_segment_size': dt_definition.protocol_details.get('max_segment_size', None),
            'packet': dt_definition.protocol_details.get('packet', None),
            'packet_size': dt_definition.protocol_details.get('packet_size', None),
            'interval': configuration['data_transfer']['iperf'].get('interval', 1),
            'apn': dt_definition.protocol_details.get('apn', None),
            'linux_congestion': dt_definition.protocol_details.get('linux_congestion', None),
            'iperf_len': dt_definition.protocol_details.get('iperf_len', None),
        }
        if dt_config['app_server_bind_interface_ip']:
            dt_config['app_server_bind_interface_ip'] = dt_config['app_server_bind_interface_ip'].strip()
        self.port = dt_config.get("port")
        self.logger.debug(f"dt_config: {dt_config}")
        return dt_config

    def _build_app_server_iperf_command(self):
        self._get_app_server_iperf_version()
        iperf_cmd = ""
        self._bind_ip = self.dt_config['app_server_bind_interface_ip']
        if self.dt_config["direction"] == "ul":
            iperf_cmd += '-s '
            iperf_cmd = self._add_iperf_optional_options_for_server(iperf_cmd)
        elif self.dt_config["direction"] == "dl":
            iperf_cmd += self._add_arg_to_cmd(flag='-c', value=self.ue_ip)
            iperf_cmd += self._add_arg_to_cmd(flag='-t', value=self.dt_config['duration'])
            # Iperf2and Iperf3 for TCP always sends max throughput, therefore setting -b makes no sense.
            if not self.dt_config["protocol"] == "tcp":
                iperf_cmd += f"-b {self.dt_config['throughput']}K "
            iperf_cmd = self._add_iperf_optional_options_for_client(iperf_cmd)

        iperf_cmd = self._add_iperf_common_options(iperf_cmd)

        return iperf_cmd

    def _build_ue_iperf_command(self):
        iperf_cmd = ""
        self.logger.debug(f"IP: {self.ue_ip}")
        self._bind_ip = self.ue_ip
        if self.dt_config["direction"] == "ul":
            iperf_cmd += self._add_arg_to_cmd(flag='-c', value=self.app_server_ip)  # traffic IP on AppServer
            iperf_cmd += self._add_arg_to_cmd(flag='-t', value=self.dt_config['duration'])
            # Iperf2 and Iperf3 for TCP always sends max throughput, therefore setting -b makes no sense.
            if not self.dt_config["protocol"] == "tcp":
                iperf_cmd += f"-b {self.dt_config['throughput']}K "
            iperf_cmd = self._add_iperf_optional_options_for_client(iperf_cmd)
        elif self.dt_config["direction"] == "dl":
            iperf_cmd += '-s '
            iperf_cmd = self._add_iperf_optional_options_for_server(iperf_cmd)

        iperf_cmd = self._add_iperf_common_options(iperf_cmd)
        self.logger.debug(f"AT IPERF: {iperf_cmd}")
        return iperf_cmd
